// Package helpers holds the code the calc suite's step definitions share:
// one place that knows how to run the calculator's declared CLI commands as
// processes and hand their stdout back to a step. Nothing here computes a
// half or a double; the process the calculator owns does that.
package helpers

import (
	"context"
	"fmt"
	"os/exec"
	"path/filepath"
	"strings"
	"time"
)

const (
	// CommandHalve and CommandDouble are the command names the calculator's
	// CLI document declares.
	CommandHalve  = "halve"
	CommandDouble = "double"

	// ExactFlag is the flag the CLI document declares on halve, which keeps
	// an odd VALUE's half instead of rounding it toward zero.
	ExactFlag = "--exact"

	// OperationHalves and OperationDoubles are the operation words a step
	// names.
	OperationHalves  = "halves"
	OperationDoubles = "doubles"

	// servicePackage is the package the CLI document says to run.
	servicePackage = "./services/calc"

	// runTimeout bounds one run of the calculator so a wedged process fails
	// the step instead of hanging the suite.
	runTimeout = 2 * time.Minute
)

// hostRoot is the directory the CLI document says to run the calculator
// from, relative to the suite test binary's working directory (tests/calc).
var hostRoot = filepath.Join("..", "..")

// OperationCommand maps the operation word a step names to the calculator
// command this concept's binding declares for it.
func OperationCommand(operation string) (string, error) {
	switch operation {
	case OperationHalves:
		return CommandHalve, nil
	case OperationDoubles:
		return CommandDouble, nil
	default:
		return "", fmt.Errorf("unknown operation %q: the calculator declares only %q and %q", operation, CommandHalve, CommandDouble)
	}
}

// RunCalc runs one declared calculator command as a process from the host
// root, as the CLI document describes, and returns its stdout verbatim,
// trailing newline included. A non-zero exit becomes an error carrying the
// command line and the process's stderr.
func RunCalc(command string, args ...string) (string, error) {
	ctx, cancel := context.WithTimeout(context.Background(), runTimeout)
	defer cancel()

	argv := append([]string{"run", servicePackage, command}, args...)
	cmd := exec.CommandContext(ctx, "go", argv...)
	cmd.Dir = hostRoot

	var stdout, stderr strings.Builder
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	if err := cmd.Run(); err != nil {
		detail := strings.TrimSpace(stderr.String())
		if detail == "" {
			detail = "no stderr"
		}
		return "", fmt.Errorf("go %s (in %s): %w: %s", strings.Join(argv, " "), hostRoot, err, detail)
	}

	return stdout.String(), nil
}

package helpers

import (
	"fmt"
	"regexp"
	"strings"
)

const (
	// ComparisonMatches and ComparisonDoesNotMatch are the two alternatives a
	// step states to say whether the printed output must have a match for the
	// step's pattern or must have none.
	ComparisonMatches      = "matches"
	ComparisonDoesNotMatch = "does not match"
)

// PrintedOutput returns the kept stdout as the text a pattern is matched
// against: the calculator's CLI document says each command prints its result
// and a newline, so the one trailing newline is dropped and everything else is
// left verbatim.
func PrintedOutput(output string) string {
	return strings.TrimSuffix(output, "\n")
}

// MatchesPattern reports whether the step's pattern, read as a Go regular
// expression, has a match in printed. A pattern Go cannot compile is an error
// against the step rather than a silent non-match.
func MatchesPattern(printed, pattern string) (bool, error) {
	expression, err := regexp.Compile(pattern)
	if err != nil {
		return false, fmt.Errorf("the step's pattern %s is not a usable regular expression: %w", pattern, err)
	}

	return expression.MatchString(printed), nil
}

package steps

import (
	"fmt"

	"fixture/conceptbodiescases/tests/calc/helpers"
)

//truebdd:concept when "operation"
func concept40523ceb26a25e37e78222ac562623f48c38b52711218d94fe5cadea337eebba(state *State, args []string) error {
	if len(args) != 3 {
		return fmt.Errorf("expected 3 captures (exactly, operation, number), got %d: %q", len(args), args)
	}
	exactly, operation, number := args[0], args[1], args[2]

	command, err := helpers.OperationCommand(operation)
	if err != nil {
		return err
	}

	var flags []string
	if exactly != "" {
		if command != helpers.CommandHalve {
			return fmt.Errorf("the calculator's %s command declares no %s flag, so %q cannot be run exactly", command, helpers.ExactFlag, operation)
		}
		flags = append(flags, helpers.ExactFlag)
	}

	output, err := helpers.RunCalc(command, append(flags, number)...)
	if err != nil {
		return err
	}

	state.Output = output

	return nil
}

package steps

import (
	"fmt"

	"fixture/conceptbodiescases/tests/calc/helpers"
)

//truebdd:concept then "output"
func concept95123e5878d35715c67b1f901cd0d6e1fcafc896021616abdece460efff6ed7e(state *State, args []string) error {
	if len(args) != 2 {
		return fmt.Errorf("expected 2 captures (comparison, pattern), got %d: %q", len(args), args)
	}
	comparison, pattern := args[0], args[1]

	if state.Output == "" {
		return fmt.Errorf("the calculator printed nothing to match %s against: no run of the calculator was kept", pattern)
	}

	printed := helpers.PrintedOutput(state.Output)

	matched, err := helpers.MatchesPattern(printed, pattern)
	if err != nil {
		return err
	}

	switch comparison {
	case helpers.ComparisonMatches:
		if !matched {
			return fmt.Errorf("the calculator printed %q, which has no match for %s", printed, pattern)
		}
	case helpers.ComparisonDoesNotMatch:
		if matched {
			return fmt.Errorf("the calculator printed %q, which has a match for %s, but the step requires none", printed, pattern)
		}
	default:
		return fmt.Errorf("unknown comparison %q: a step says either %q or %q", comparison, helpers.ComparisonMatches, helpers.ComparisonDoesNotMatch)
	}

	return nil
}

package steps

func Register(suite Registrar) {

	suite.Step("^the Owner (?:(exactly) )?(halves|doubles) (-?\\d+)$", concept40523ceb26a25e37e78222ac562623f48c38b52711218d94fe5cadea337eebba)

	suite.Step("^the calculator's output (matches|does not match) (.+)$", concept95123e5878d35715c67b1f901cd0d6e1fcafc896021616abdece460efff6ed7e)
}
